settings.customCss:
body > #gf-tree .gf-filter-header{
border-bottom: none;
}
body > #gf-tree .gf-filter-contents{
overflow: visible;
}

.gf-block-title .h3{
padding: 20px 20px 20px 0;
display: flex;
grid-gap: 10px;
justify-content: space-between;
align-items: center;
}
.gf-clear{
display: none;
}
body > #gf-tree .gf-filter-header{
padding: 0;
}
.gf-option-block .gf-block-title .h3:after{
font-size: 22px;
    height: 0.5em;
    margin-top: -0.5em;
}
.gf-scroll{
margin-bottom: 27px;
}
.gf-block-content{
margin-top: 0;
padding-right: 25px;
}
.gf-Checkbox, .gf-RadioButton{
width: 20px;
    height: 20px;
    margin-right: 13px;
    flex: 0 0 20px;
    min-width: 20px;
}

.offcanvas-open #gf-overlay{
opacity: 0.2;
}
.spf-product-card{
padding-bottom: 0;
    margin-bottom: 0;
}
span.gf-summary{
font-size: 17px;
}
.spf-product-card img.spf-product-card__image{
height: 100%;
}
body > #gf-tree .globo-selected-items-wrapper > .globo-selected-items{
  padding-left: 0 !important;
    padding-top: 0 !important;
}
body > #gf-tree .globo-selected-items-wrapper > .globo-selected-items .clear-refinements{
  padding: 7px 18px;
    font-size: 15px;
}
.gf-option-block[data-filter-type="color"] ul.gf-option-box{
column-count: 2;
}


@media only screen and (max-width: 767px) {
img.spf-product-card__image{
height: 100%;
}
.gf-block-title .h3{
padding: 25px 16px 25px 0;
}
.gf-block-content{
padding: 0 16px 0 0;
}
span.gf-summary{
flex: 1;
        order: 0;
}
.gf-offcanvas .gf-filter-trigger{
flex: none;
margin-bottom: 0px;
}
.gf-offcanvas .gf-filter-trigger .btn-text{
display: none;
}
span.gf-summary{
    order: -1;
}
.gf-actions .gf-filter-selection{
flex: none;
        flex-shrink: 0;
margin-bottom: 0;
}
.gf-filter-selection .sort-by{
border: none;
        background: transparent;
flex-direction: row-reverse;
}
.sort-by::before{
position: static;
    margin-left: 5px;
}
.sort-by-toggle{
padding: 0;
height: auto;
    line-height: 1.5em;
    font-size: 15px;
}
span.gf-summary{
font-size: 15px;
}
