@media only screen and (min-width: 768px) {
.gf-filter-trigger{
order: 1;
}
#gf-controls-container .globo-selected-items-wrapper{
order: 2;
}
}
.gf-offcanvas .gf-refine-toggle-mobile{
border: none !important;
}
.gf-offcanvas .gf-refine-toggle-mobile span{
padding: 0;
}
#gf_pagination_wrap button.gf-loadmore-btn{
    background: #F3F3F3;
    border-color: #F3F3F3;
    color: var(--brand-primary-color, #000);
    padding: 14px 27px;
    transition: background-color 0.4s ease-out, color 0.3s ease-out;
    font-size: 17px;
    line-height: 1em;
    height: auto;
    margin: 0;
    border-radius: 100px;
}
#gf_pagination_wrap button.gf-loadmore-btn:hover{
color: var(--brand-primary-color-contrast, #FFF);
background: #000000;
        border-color: #000000;
}

#gf_pagination_wrap{
margin-top: 30px;
    margin-bottom: 20px;
padding-top: 0;
}

#gf-tree .noUi-handle, #gf-tree .noUi-connect{
background: #000;
}

settings.custom_css:
.frcp-wishlist-wrapper{
    width: auto;
    margin: 0;
}
.frcp-wishlist-btn--add, .frcp-wishlist-btn--remove{
    padding: 5px;
}
.frcp-wishlist-btn--remove svg{
    fill: currentColor;
}
.frcp-wishlist-link-wrapper .frcp-wishlist-link{
background: black;
    border-radius: 50%;
    color: white;
}
.frcp-wishlist-link-wrapper .frcp-wishlist-link-count{
    border-radius: 50%;
    background: white;
    font-weight: 600;
   box-shadow: 0 0 2px #000;
}
